(()=>{
 'use strict';
 const data=window.UA_CARD_DETAILS;if(!data)return;
 const exact=new Map(data.cards.map(c=>[c.number,c]));
 const base=n=>String(n||'').replace(/_p\d+$/,'');
 const getNative=card=>exact.get(base(card.number));
 const languageName=language=>language==='ja'?'日文':language==='en'?'英文':'未标注';
 function artLanguage(card){if(/\/jp\//.test(card.image||'')||/^UA/.test(card.number||''))return 'ja';if(/\/na\/|UA-EN/.test(card.image||'')||/^UE/.test(card.number||''))return 'en';return '';}
 function resolve(card,language){const native=getNative(card);if(!native)return null;if(language===native.language)return native;const relation=data.links.find(l=>l.verified&&(l.ja===native.number||l.en===native.number));if(!relation)return null;const target=exact.get(relation[language]);return target?.language===language?target:null;}
 function available(card){return ['en','ja'].filter(language=>resolve(card,language));}
 window.MetaLabUACardText={resolve,available,artLanguage,languageName,getNative,coverage:data.coverage};
})();
